"멀리 떨어진 친척에게 전화를 걸어 요즘 읽는 책 이야기를 꺼냈더니 밤이 깊도록 통화가 이어졌다":"给远在外地的亲戚打电话，聊起最近读的书，电话一直打到夜深",
"멀리 사는 {0}에게 안부 전화를 걸어 요즘 식사는 어떠냐고 묻자 한참 어릴 적 이야기가 따라 나왔다":"给住得远的{0}打电话问候，问最近吃得怎么样，聊着聊着扯出好多小时候的事",
"멀리 사는 조카가 전화를 받아 요즘 무슨 반찬을 해 먹냐고 묻자 한참 신이 나서 대답을 늘어놓았다":"住得远的侄子接了电话，问我最近都做什么菜吃，我兴高采烈地回答了好久",
"멀리 사는 조카에게 안부 전화를 걸어 요즘 식사는 어떠냐고 묻자 한참 어릴 적 이야기가 따라 나왔다":"给住得远的侄子打电话问候，问最近吃得怎么样，聊着聊着扯出好多小时候的事",
"멀리 이사 간 친구에게 짧게 안부 문자를 보냈더니 긴 답장이 와서 내내 휴대폰을 쥐고 웃었다":"给搬到远方的朋友简单发了条问候短信，收到一长串回复，一直攥着手机笑",
"며칠 뒤 우편함에 도착한 결과지를 열어 모든 수치가 정상 범위에 걸쳐 있는 걸 확인하고 한숨 돌렸다":"几天后打开邮箱里收到的结果单，确认所有数值都落在正常范围内，松了口气",
"면 소재지 운동장에서 열린 작은 대회에 번호표를 달고 나가 두 판을 이겼고, 구경 온 어른들이 박수를 쳤다":"挂上号码牌去参加乡里操场办的小比赛，赢了两场，来看的大人们都鼓了掌",
