"명절 날 큰상 한쪽에 작은 의자를 끌어다 놓고 어른들 사이에 앉아 달콤한 과일을 받았다":"节日那天把小凳子拖到大饭桌一角，坐在大人们中间，分到了甜甜的水果",
"명절 전날 식구들이 부엌에 모여 전을 부치며 서로 기름 튀는 손등을 걱정하다가 몇 개를 몰래 집어 먹었다":"节日前一天，一家人聚在厨房煎饼，互相担心油溅到手背，偷偷拿了几块吃",
"몇 달을 풀었다 감았다 하던 끝에 마침내 하나가 완성되어, 책상에 올려 두고 밤마다 들여다보았다":"拆了绕、绕了拆好几个月，终于做成了一件，放在桌上，每晚都要看一看",
"모든 연락을 뒤집어 놓고 베란다 의자에 앉아, 건너편 옥상의 빨래가 마르는 걸 오래 바라보았다":"把所有联系都翻过去扣着，坐在阳台椅子上，久久望着对面屋顶晾着的衣服慢慢变干",
"모래밭에 구덩이를 파고 물을 길어다 붓다가, 성이 무너지는 소리에 깔깔 웃었다":"在沙地上挖坑，提水来灌，听到城堡塌掉的声音，咯咯笑了起来",
"모르는 애들 틈에 끼어 해 질 녘까지 공터에서 공을 차다가, 흙투성이 얼굴로 돌아왔다":"挤进不认识的孩子们当中，在空地上踢球踢到日落，满脸泥巴地回了家",
"모임 가입":"加入聚会",
"모임 날 비가 쏟아져 다들 우산을 쓰고 흩어져, 준비한 도안은 가방에 도로 들어갔다":"聚会那天大雨倾盆，大家撑着伞各自散了，准备好的图样又收回了包里",
"모임 날 아침 비가 쏟아져 우산을 들고 나섰다가 미끄러운 길이 겁나 대문 앞에서 돌아섰다":"聚会那天早上大雨倾盆，撑着伞出了门，怕路滑，在大门前转身回去了",
"모임 날을 달력에 적어 둔 걸 깜박해서, 문 닫힌 회관 앞에서 준비해 온 재료만 만지작거렸다":"忘了把聚会日期记在日历上，在关了门的会馆前，只摆弄着带来的材料",
"모임 도중 일터에서 급한 전화가 연달아 와서 자리를 뜨는 바람에 정작 이야기는 한마디도 못 나눴다":"聚会中途工作上的急电接连打来，只好离席，结果一句话也没聊上",
"모임 선배가 내 작품 옆에 나란히 걸자며 신입 몫의 자리를 비워 둔 걸 보고, 나도 몇 가지를 알려 주었다":"聚会前辈把我的作品挂在他的旁边，给新人留了位置，我也教了他几招",
"모임에 가는 길에 버스를 잘못 타 한 시간을 돌아가느라 도착했을 땐 이미 정리가 끝나고 있었다":"去聚会的路上坐错了公交，绕了一个小时，到的时候已经在收拾了",
"모임에서 다들 아는 사이처럼 어울려 말을 붙일 틈이 없어 음료만 홀짝이다 일찍 나왔다":"聚会上大家像老熟人一样玩在一起，没我插话的空档，只抿着饮料，早早离开了",
"모임이 끝나고 회비를 정산하는데 지갑을 두고 와서 옆자리 사람에게 빌리느라 얼굴이 붉어졌다":"聚会结束后结算会费，才发现忘带钱包，向旁边的人借钱，脸涨得通红",
"모처럼 나선 길에 약 한 봉지를 집에 두고 나온 걸 알고, 첫 정류장에서 다시 돌아가야 했다":"难得出门，发现落了一包药在家里，到第一站又得折回去",
"모처럼 놀러 나서려는데 무릎이 말을 안 들어, 현관 앞 의자에 앉아 신발만 내려다보았다":"难得要出门玩，膝盖却不听使唤，坐在玄关的椅子上只低头看着鞋",
"모처럼 다 같이 근처 식당에 가서 둥근 탁자에 둘러앉아 한 접시씩 덜어 나누어 먹었다":"难得大家一起去附近的饭馆，围坐在圆桌边，一人分一盘地分着吃",
"모처럼 쉬려던 주말에 급한 연락이 와서, 예약해 둔 약속을 취소하고 책상 앞으로 돌아왔다":"难得想休息的周末来了急电，只好取消订好的约，回到了桌前",
"모처럼 잡은 약속에 나갔더니 비가 쏟아져, 우산 쓴 채 카페 구석에서 한 시간만 앉아 있다 왔다":"难得约好了去赴约，却下起大雨，撑着伞在咖啡馆角落只坐了一个小时就回来了",
"목돈 걱정을 덜려고 시작한 부업이 석 달 만에 통장 잔액을 한 줄 늘려 놓았다":"为了减轻一大笔钱的压力开始做兼职，三个月后存折余额多了一行",
