"저녁 상에서 마지막 남은 튀김 하나를 두고 식구와 젓가락을 맞부딪치다 둘 다 웃고 반씩 나눴다":"晚饭桌上为最后剩下的一块炸物，和家人的筷子撞在一起，两个人都笑了，一人分了一半",
"저녁 상을 거의 차렸는데 가스가 떨어져 찌개가 덜 익은 채로 불을 다시 켜느라 식구들이 배고파했다":"晚饭差不多摆好了，煤气用完了，炖菜没熟透，重新点火，家人都饿了",
