"저녁 설거지를 맡았는데 수도가 갑자기 끊겨 그릇을 쌓아 둔 채 물이 다시 나오기만 기다렸다":"轮到我洗晚上的碗，水突然停了，把碗堆在那儿，只等水再来",
"저녁 약속을 지키려고 서둘러 갔는데 막차가 끊겨 식구들은 이미 먹고 상이 치워져 있었다":"为了赶上晚饭的约定匆匆赶去，末班车已经没了，家人早已吃完，饭桌也收了",
