"저녁마다 중고 물건을 닦아 사진을 찍어 올렸더니, 사흘 만에 첫 구매자가 나타나서 주소를 물어 왔다":"每晚擦干净二手物品拍照上架，三天后第一位买家出现了，问我地址",
"저녁에 공부하려던 날 갑자기 손님이 찾아와 책은 펼쳐 보지도 못한 채 밤이 깊어 버렸다":"打算晚上学习的那天，突然来了客人，书连翻都没翻，夜就深了",
"저녁에 읽으려던 그림책을 책상에 올려 두고 야근을 하다가 열어 보지도 못하고 잠들었다":"把晚上想读的绘本放在桌上，加班之后，连翻都没翻开就睡着了",
"저녁에 한 번 더 확인하겠다던 숫자가 아침에 보니 줄이 하나 밀려 있어서, 반나절을 거슬러 찾았다":"说好晚上再确认一遍的数字，早上一看错了一行，花了大半天往回查",
