"전문 자격":"专业资格",
"전문가":"专家",
"전화기 버튼을 잘못 눌러 전혀 다른 곳에 걸려 놓고 한참 사과하느라 본래 하려던 말을 잊었다":"按错了电话按键，打到了完全不相干的地方，一个劲儿地道歉，把本来想说的话忘了",
